mapper.select:
SELECT COUNT(*) FROM label_entry_node n JOIN label_data_entry e ON e.id = n.entry_id AND e.deleted = 0 JOIN label_task t ON t.id = n.task_id AND t.deleted = 0 JOIN label_project p ON p.id = t.project_id AND p.deleted = 0
n.deleted = 0 AND n.task_id = #{taskId} AND e.batch_id = #{batchId} AND n.operator_id = #{userId}
AND n.status IN #{s}
AND (e.entry_name LIKE CONCAT('%', #{keyword}, '%') OR e.entry_no LIKE CONCAT('%', #{keyword}, '%') OR t.task_name LIKE CONCAT('%', #{keyword}, '%') OR p.project_name LIKE CONCAT('%', #{keyword}, '%'))

SELECT n.id AS entryNodeId, e.id AS entryId, e.entry_no AS entryNo, e.entry_name AS entryName, e.batch_id AS batchId, COALESCE(b.batch_name, b.batch_no) AS batchName, t.id AS taskId, t.task_no AS taskNo, t.task_name AS taskName, p.id AS projectId, p.project_name AS projectName, n.node_key AS nodeKey, n.node_type AS nodeType, n.status AS nodeStatus, n.operator_id AS operatorId, n.claim_time AS claimTime, n.skip_time AS skipTime, n.abandon_time AS abandonTime, n.done_time AS doneTime, e.label_status AS labelStatus, e.review_status AS reviewStatus, (SELECT ja.job_id FROM label_job_asset ja JOIN label_asset a ON a.id = ja.asset_id AND a.deleted = 0 WHERE a.entry_id = e.id ORDER BY ja.job_id DESC LIMIT 1) AS jobId FROM label_entry_node n JOIN label_data_entry e ON e.id = n.entry_id AND e.deleted = 0 JOIN label_task t ON t.id = n.task_id AND t.deleted = 0 JOIN label_project p ON p.id = t.project_id AND p.deleted = 0 LEFT JOIN label_asset_batch b ON b.id = e.batch_id AND b.deleted = 0
n.deleted = 0 AND n.task_id = #{taskId} AND e.batch_id = #{batchId} AND n.operator_id = #{userId}
AND n.status IN #{s}
AND (e.entry_name LIKE CONCAT('%', #{keyword}, '%') OR e.entry_no LIKE CONCAT('%', #{keyword}, '%') OR t.task_name LIKE CONCAT('%', #{keyword}, '%') OR p.project_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY n.update_time DESC, n.id DESC LIMIT #{offset}, #{limit}

SELECT n.id AS entryNodeId, e.id AS entryId, e.entry_no AS entryNo, e.entry_name AS entryName, e.batch_id AS batchId, COALESCE(b.batch_name, b.batch_no) AS batchName, t.id AS taskId, t.task_no AS taskNo, t.task_name AS taskName, p.id AS projectId, p.project_name AS projectName, n.node_key AS nodeKey, n.node_type AS nodeType, n.status AS nodeStatus, n.operator_id AS operatorId, n.claim_time AS claimTime, n.skip_time AS skipTime, n.abandon_time AS abandonTime, n.done_time AS doneTime, e.label_status AS labelStatus, e.review_status AS reviewStatus, (SELECT ja.job_id FROM label_job_asset ja JOIN label_asset a ON a.id = ja.asset_id AND a.deleted = 0 WHERE a.entry_id = e.id ORDER BY ja.job_id DESC LIMIT 1) AS jobId FROM label_entry_node n JOIN label_data_entry e ON e.id = n.entry_id AND e.deleted = 0 JOIN label_task t ON t.id = n.task_id AND t.deleted = 0 JOIN label_project p ON p.id = t.project_id AND p.deleted = 0 LEFT JOIN label_asset_batch b ON b.id = e.batch_id AND b.deleted = 0
n.deleted = 0 AND n.task_id = #{taskId} AND e.batch_id = #{batchId} AND n.operator_id IS NOT NULL
AND n.status IN #{s}
AND (e.entry_name LIKE CONCAT('%', #{keyword}, '%') OR e.entry_no LIKE CONCAT('%', #{keyword}, '%') OR t.task_name LIKE CONCAT('%', #{keyword}, '%') OR p.project_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY n.update_time DESC, n.id DESC LIMIT #{offset}, #{limit}
